async (page) => {
  const fs = require('fs');
  const path = require('path');
  const root = '/tmp/mcp-workspace';
  const emailRe = /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g;
  const found = new Set();
  const textExts = new Set(['.txt']);
  function walk(dir) {
    let entries;
    try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch { return; }
    for (const e of entries) {
      const full = path.join(dir, e.name);
      if (e.isDirectory()) walk(full);
      else if (e.isFile()) {
        const ext = path.extname(e.name).toLowerCase();
        if (textExts.has(ext)) {
          try {
            const data = fs.readFileSync(full, 'utf8');
            const matches = data.match(emailRe);
            if (matches) matches.forEach(m => found.add(m));
          } catch {}
        }
      }
    }
  }
  walk(root);
  const sorted = [...found].sort();
  fs.writeFileSync('/tmp/mcp-workspace/unique_emails.txt', sorted.join('\n') + (sorted.length ? '\n' : ''));
  return { count: sorted.length, emails: sorted };
};

